import { totalEmCentavos } from './main.js';

describe('totalEmCentavos', () => {
  test('soma os itens convertidos e acrescenta o frete como número', () => {
    const pedido = { itens: [{ quantidade: '2', precoCentavos: '1250' }], frete: '800' };
    expect(totalEmCentavos(pedido)).toBe(3300);
  });
  test('aceita espaços nas bordas do frete', () => {
    const pedido = { itens: [{ quantidade: '1', precoCentavos: '990' }, { quantidade: '3', precoCentavos: '100' }], frete: ' 650 ' };
    expect(totalEmCentavos(pedido)).toBe(1940);
  });
  test('frete zero e pedido sem itens devolvem zero', () => {
    expect(totalEmCentavos({ itens: [], frete: '0' })).toBe(0);
  });
  test('o resultado é sempre número, não texto', () => {
    const total = totalEmCentavos({ itens: [{ quantidade: '1', precoCentavos: '500' }], frete: '250' });
    expect(typeof total).toBe('number');
    expect(total).toBe(750);
  });
});

