import { sortearFace } from './main.js';

describe('sortearFace', () => {
  test('o início do intervalo cai na primeira face', () => {
    expect(sortearFace(() => 0)).toBe(1);
  });
  test('valores de [0, 1) são divididos em seis faixas', () => {
    expect(sortearFace(() => 0.2)).toBe(2);
    expect(sortearFace(() => 0.5)).toBe(4);
  });
  test('quase 1 continua na sexta face', () => {
    expect(sortearFace(() => 0.9999999999999999)).toBe(6);
  });
  test('valores fora de [0, 1) lançam RangeError', () => {
    expect(() => sortearFace(() => 1)).toThrow(RangeError);
    expect(() => sortearFace(() => -0.1)).toThrow(RangeError);
  });
  test('sem função injetada, o resultado é sempre uma face válida', () => {
    for (let i = 0; i < 100; i++) {
      const face = sortearFace();
      expect(Number.isInteger(face) && face >= 1 && face <= 6).toBe(true);
    }
  });
});

