export function medirTrajeto(origem, destino) {
  const dx = destino.x - origem.x;
  const dy = destino.y - origem.y;
  return {
    reta: Math.sqrt(dx * dx + dy * dy),
    grade: Math.abs(dx) + Math.abs(dy),
    lado: Math.max(Math.abs(dx), Math.abs(dy)),
  };
}

