  validarNumero(pesoGramas, 'pesoGramas');
  validarNumero(distanciaKm, 'distanciaKm');
  const kgExtras = Math.max(0, Math.ceil(pesoGramas / 1000) - 1);
  const kmExtras = Math.max(0, Math.ceil(distanciaKm - 5));
