import { serializarRanking, restaurarRanking } from './main.js';

describe('serializarRanking', () => {
  test('gera pares ordenados pelo nome', () => {
    expect(serializarRanking(new Map([['Bia', 7], ['Ana', 9]]))).toBe('[["Ana",9],["Bia",7]]');
  });
  test('ranking vazio vira array vazio', () => {
    expect(serializarRanking(new Map())).toBe('[]');
  });
  test('entrada que não é Map lança TypeError', () => {
    expect(() => serializarRanking({ Ana: 9 })).toThrow(TypeError);
  });
});

describe('restaurarRanking', () => {
  test('ida e volta preserva os pares', () => {
    const original = new Map([['Ana', 9], ['Bia', 7]]);
    const restaurado = restaurarRanking(serializarRanking(original));
    expect([...restaurado.entries()]).toEqual([['Ana', 9], ['Bia', 7]]);
  });
  test('texto que não é JSON válido devolve Map vazio, sem lançar', () => {
    expect(restaurarRanking('{ruim').size).toBe(0);
  });
  test('JSON que não é array devolve Map vazio', () => {
    expect(restaurarRanking('{"Ana":3}').size).toBe(0);
  });
  test('descarta pares com pontos inválidos ou mal formados', () => {
    const restaurado = restaurarRanking('[["Ana",-1],["Caio",2.5],["Dara",3],["Eva"]]');
    expect([...restaurado.entries()]).toEqual([['Dara', 3]]);
  });
});

