export function serializarRanking(ranking) {
  if (!(ranking instanceof Map)) throw new TypeError('ranking deve ser Map');
  const pares = [...ranking.entries()].sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0));
  return JSON.stringify(pares);
}

export function restaurarRanking(texto) {
  const mapa = new Map();
  let dados;
  try {
    dados = JSON.parse(texto);
  } catch {
    return mapa;
  }
  if (!Array.isArray(dados)) return mapa;
  for (const par of dados) {
    if (!Array.isArray(par) || par.length !== 2) continue;
    const [nome, pontos] = par;
    if (typeof nome !== 'string' || !Number.isInteger(pontos) || pontos < 0) continue;
    mapa.set(nome, pontos);
  }
  return mapa;
}

