import { existePar } from './main.js';

describe('existePar', () => {
  test('encontra dois valores que somam o alvo', () => {
    expect(existePar([2, 7, 11, 15], 9)).toBe(true);
    expect(existePar([3, 2, 4], 6)).toBe(true);
  });
  test('valores repetidos em posições diferentes contam', () => {
    expect(existePar([3, 3], 6)).toBe(true);
  });
  test('o mesmo elemento não pode ser usado duas vezes', () => {
    expect(existePar([3], 6)).toBe(false);
  });
  test('sem par devolve false, e lista vazia também', () => {
    expect(existePar([1, 2, 3], 10)).toBe(false);
    expect(existePar([], 0)).toBe(false);
  });
  test('entrada que não é array lança TypeError', () => {
    expect(() => existePar('123', 3)).toThrow(TypeError);
  });
  test('lista grande é resolvida com uma única varredura', () => {
    const grande = Array.from({ length: 200000 }, (_, i) => i * 2);
    expect(existePar(grande, 399996)).toBe(true);
    expect(existePar(grande, 399997)).toBe(false);
  });
});

