import { criarVeiculo } from './main.js';

describe('criarVeiculo', () => {
  test('descrever usa marca e ano do próprio veículo', () => {
    expect(criarVeiculo('Volks', 1980).descrever()).toBe('Volks (1980)');
  });
  test('descrever não é propriedade própria de cada veículo', () => {
    expect(Object.hasOwn(criarVeiculo('Volks', 1980), 'descrever')).toBe(false);
  });
  test('marca e ano são as únicas propriedades próprias', () => {
    expect(Object.keys(criarVeiculo('Volks', 1980))).toEqual(['marca', 'ano']);
  });
  test('veículos diferentes compartilham o mesmo método', () => {
    const a = criarVeiculo('A', 1);
    const b = criarVeiculo('B', 2);
    expect(a.descrever === b.descrever).toBe(true);
  });
  test('alterar o ano de um veículo não muda o outro', () => {
    const a = criarVeiculo('A', 1);
    const b = criarVeiculo('B', 2);
    a.ano = 3;
    expect(a.descrever()).toBe('A (3)');
    expect(b.descrever()).toBe('B (2)');
  });
});

