export class Plano {
  #preco;

  constructor(nome, preco) {
    if (!Number.isInteger(preco) || preco < 0) throw new RangeError('preco deve ser inteiro não negativo');
    this.nome = nome;
    this.#preco = preco;
  }

  get preco() {
    return this.#preco;
  }

  descricao() {
    return this.nome + ' por ' + this.#preco + ' centavos';
  }
}

export class PlanoAnual extends Plano {
  constructor(nome, precoMensal) {
    this.meses = 12;
    super(nome, precoMensal);
  }

  descricao() {
    return 'Anual: ' + this.nome;
  }
}

