export const TAXA_BASE = 500;

export function calcularFrete(pesoGramas) {
  if (typeof pesoGramas !== 'number') throw new TypeError('peso deve ser número');
  if (!Number.isFinite(pesoGramas) || pesoGramas < 0) throw new RangeError('peso deve ser finito e não negativo');
  if (pesoGramas >= 5000) return 1500;
  if (pesoGramas >= 1000) return 900;
  return TAXA_BASE;
}

