const codigo = linhaStatus.split(' ')[1];
const headers = {};
for (const linha of linhasHeaders) {
  const indice = linha.indexOf(':');
  headers[linha.slice(0, indice).toLowerCase()] = linha.slice(indice + 1).trim();
}

