import { estaVigente, diaDoPeriodo } from './main.js';

describe('estaVigente', () => {
  test('inclui o instante de início', () => {
    expect(estaVigente('2026-03-01T00:00:00Z', '2026-03-10T00:00:00Z', '2026-03-01T00:00:00Z')).toBe(true);
  });
  test('exclui o instante de fim', () => {
    expect(estaVigente('2026-03-01T00:00:00Z', '2026-03-10T00:00:00Z', '2026-03-10T00:00:00Z')).toBe(false);
  });
  test('compara instantes, não textos: -03:00 às 00:00 é 03:00 UTC', () => {
    const inicio = '2026-03-01T00:00:00-03:00';
    const fim = '2026-03-10T00:00:00Z';
    expect(estaVigente(inicio, fim, '2026-03-01T02:59:59Z')).toBe(false);
    expect(estaVigente(inicio, fim, '2026-03-01T03:00:00Z')).toBe(true);
  });
  test('texto de data inválido lança RangeError', () => {
    expect(() => estaVigente('nao é data', '2026-03-10T00:00:00Z', '2026-03-05T00:00:00Z')).toThrow(RangeError);
  });
  test('fim que não é posterior ao início lança RangeError', () => {
    expect(() => estaVigente('2026-03-10T00:00:00Z', '2026-03-01T00:00:00Z', '2026-03-05T00:00:00Z')).toThrow(RangeError);
  });
});

describe('diaDoPeriodo', () => {
  test('devolve o dia em UTC', () => {
    expect(diaDoPeriodo('2026-03-01T23:30:00-03:00')).toBe('2026-03-02');
