// Intervalo assíncrono: produz inicio..fim, com cursor próprio para cada iterador.
let cursor = 0;

export function criarIntervaloAsync(inicio, fim) {
  cursor = inicio;
  return {
    [Symbol.asyncIterator]() {
      return {
        async next() {
          if (cursor >= fim) return { value: undefined, done: true };
          const valor = cursor;
          cursor += 1;
          return { value: valor, done: false };
        },
      };
    },
  };
}

