import { usarRecurso } from './main.js';

function criarEstado() {
  const estado = { aberto: false, fechamentos: 0 };
  estado.abrir = async () => {
    estado.aberto = true;
    return {
      valor: 'conexao',
      fechar() {
        estado.aberto = false;
        estado.fechamentos += 1;
      },
    };
  };
  return estado;
}

describe('usarRecurso', () => {
  test('devolve o resultado de usar e fecha ao final', async () => {
    const estado = criarEstado();
    expect(await usarRecurso(estado.abrir, async valor => valor + '!')).toBe('conexao!');
    expect(estado.aberto).toBe(false);
    expect(estado.fechamentos).toBe(1);
  });
  test('o recurso continua aberto durante o uso', async () => {
    const estado = criarEstado();
    let abertoDurante = null;
    await usarRecurso(estado.abrir, () => {
      abertoDurante = estado.aberto;
      return 1;
    });
    expect(abertoDurante).toBe(true);
  });
  test('fecha mesmo quando usar lança erro', async () => {
    const estado = criarEstado();
    let erro = null;
    try {
      await usarRecurso(estado.abrir, () => {
        throw new Error('falha de uso');
      });
    } catch (falha) {
      erro = falha;
    }
    expect(erro && erro.message).toBe('falha de uso');
    expect(estado.aberto).toBe(false);
    expect(estado.fechamentos).toBe(1);
  });
  test('fecha mesmo quando a promessa de usar rejeita', async () => {
    const estado = criarEstado();
    let erro = null;
    try {
      await usarRecurso(estado.abrir, async () => {
        throw new Error('rejeitou');
      });
    } catch (falha) {
      erro = falha;
    }
    expect(erro && erro.message).toBe('rejeitou');
    expect(estado.fechamentos).toBe(1);
  });
  test('falha ao abrir não chama usar', async () => {
    let usou = false;
    let erro = null;
    try {
      await usarRecurso(async () => {
        throw new Error('sem acesso');
      }, () => {
        usou = true;
      });
    } catch (falha) {
      erro = falha;
    }
    expect(erro && erro.message).toBe('sem acesso');
    expect(usou).toBe(false);
  });
  test('abrir e usar precisam ser funções', async () => {
    let erro = null;
    try {
      await usarRecurso(null, () => 1);
    } catch (falha) {
      erro = falha;
    }
    expect(erro instanceof TypeError).toBe(true);
  });
});

