// Validação declarativa: cada regra descreve o tipo esperado; os erros carregam o caminho do campo.
export function validar(regra, valor) {
  const erros = [];
  coletar(regra, valor, '', erros);
  return erros.length === 0 ? { ok: true, valor } : { ok: false, erros };
}

function coletar(regra, valor, caminho, erros) {
  if (valor === undefined && regra.opcional) return;
  if (regra.tipo === 'objeto') {
    if (typeof valor !== 'object' || valor === null || Array.isArray(valor)) {
      erros.push({ caminho, mensagem: 'deve ser objeto' });
      return;
    }
    for (const [campo, subRegra] of Object.entries(regra.campos)) {
      coletar(subRegra, valor[campo], campo, erros);
    }
    return;
  }
  if (regra.tipo === 'lista') {
    if (!Array.isArray(valor)) {
      erros.push({ caminho, mensagem: 'deve ser lista' });
    }
    return;
  }
  if (typeof valor !== regra.tipo) erros.push({ caminho, mensagem: 'deve ser ' + regra.tipo });
}

