import { executarOperacao } from './main.js';

function criarLogger() {
  const registros = [];
  return {
    registros,
    info: registro => registros.push(registro),
    error: registro => registros.push(registro),
  };
}

describe('executarOperacao', () => {
  test('sucesso devolve o resultado e registra id, nome, status e duração', async () => {
    const logger = criarLogger();
    const tempos = [100, 135];
    const resultado = await executarOperacao('gerar', () => 42, { id: 'op-1', relogio: () => tempos.shift(), logger });
    expect(resultado).toBe(42);
    expect(logger.registros).toEqual([{ evento: 'operacao', id: 'op-1', nome: 'gerar', status: 'ok', duracaoMs: 35 }]);
  });
  test('operação assíncrona bem-sucedida é aguardada', async () => {
    const logger = criarLogger();
    const tempos = [0, 4];
    const resultado = await executarOperacao('buscar', async () => 'dados', { id: 'op-2', relogio: () => tempos.shift(), logger });
    expect(resultado).toBe('dados');
    expect(logger.registros[0].duracaoMs).toBe(4);
  });
  test('falha registra a causa e a duração e lança erro com cause', async () => {
    const logger = criarLogger();
    const tempos = [0, 7];
    const original = new Error('timeout no provedor externo');
    let erro = null;
    try {
      await executarOperacao('login', async () => {
        throw original;
      }, { id: 'op-3', relogio: () => tempos.shift(), logger });
    } catch (falha) {
      erro = falha;
    }
    expect(erro && erro.cause).toBe(original);
    expect(logger.registros).toEqual([{ evento: 'operacao', id: 'op-3', nome: 'login', status: 'falha', duracaoMs: 7, causa: 'timeout no provedor externo' }]);
  });
  test('a mensagem pública não repete o erro original', async () => {
    const logger = criarLogger();
    const tempos = [0, 1];
    let erro = null;
    try {
      await executarOperacao('login', () => {
        throw new Error('timeout no provedor externo');
      }, { id: 'op-4', relogio: () => tempos.shift(), logger });
    } catch (falha) {
      erro = falha;
    }
    expect(erro && erro.message).toBe('Operação login falhou');
  });
});

